package cache

// EmptyItemFactory определяет сигнатуру фабричной функции, генерирующей чистый (нулевой) экземпляр объекта V.
// Вызывается кодеками рантайма для легитимной аллокации памяти под дженерик-типы перед их десериализацией.
type EmptyItemFactory[V any] func() V

// Envelope — универсальный строго типизированный (Generic) конверт-контейнер для распределенного кэширования.
//
// Пакует в себя две ключевые составляющие:
//  1. Value: полезную нагрузку (Payload) бизнес-данных типа V.
//  2. DieAt: жесткий временной потолок валидности пакета (Unix Timestamp), предотвращающий чтение протухшего кэша.
type Envelope[V any] struct {
	Value V     // Целевой кэшируемый объект доменной логики или DAL-слоя
	DieAt int64 // Абсолютная временная метка смерти пакета (Unix Time) для защиты от Stale Cache
}
